function searchForm(q='',hero=false){return `<form class="search-form ${hero?'':'browse-search'}" data-search><span class="search-glyph" aria-hidden="true">⌕</span><input type="search" name="q" value="${esc(q)}" placeholder="ค้นหาชื่อไอเทม สัตว์ สูตรคราฟต์ หรือวิธีเล่น…" aria-label="ค้นหาข้อมูลเกม" autocomplete="off"><button type="submit">ค้นหา <span aria-hidden="true">↗</span></button></form>`}
